const require_browser = require("../utils/browser.js");
const require_defaults = require("../utils/defaults.js");
let react = require("react");
//#region src/useLongPress/index.ts
function isTouchEvent(ev) {
	return "touches" in ev;
}
function preventDefault(ev) {
	if (!isTouchEvent(ev)) return;
	if (ev.touches.length < 2 && ev.preventDefault) ev.preventDefault();
}
const useLongPress = (callback, { isPreventDefault = true, delay = 300 } = require_defaults.defaultOptions) => {
	const timeout = (0, react.useRef)();
	const target = (0, react.useRef)();
	const start = (0, react.useCallback)((event) => {
		if (isPreventDefault && event.target) {
			require_browser.on(event.target, "touchend", preventDefault, { passive: false });
			target.current = event.target;
		}
		timeout.current = setTimeout(() => callback(event), delay);
	}, [
		callback,
		delay,
		isPreventDefault
	]);
	const clear = (0, react.useCallback)(() => {
		timeout.current && clearTimeout(timeout.current);
		if (isPreventDefault && target.current) require_browser.off(target.current, "touchend", preventDefault);
	}, [isPreventDefault]);
	return {
		onMouseDown: (e) => start(e),
		onTouchStart: (e) => start(e),
		onMouseUp: clear,
		onMouseLeave: clear,
		onTouchEnd: clear
	};
};
//#endregion
exports.useLongPress = useLongPress;
